template <typename I1, typename I2,
          typename Difference = decltype(std::declval<I1>() - std::declval<I2>())>
auto operator-(const I1& lhs, const I2& rhs)
// SFINAE: Enable if Iterators are compatible (e.g., not the same type, or derived)
-> std::enable_if_t<
    !std::is_same_v<I1, I2>,
    Difference
>
{
    // Implementation uses the subtraction defined for the underlying types
    return lhs - rhs;
}

// NOTE: Diff deduction in template arguments triggers SFINAE early
// Trailing return type (using std::enable_if_t) provides the final return type
